SELECT mr.name, mr.schedule_date FROM `tabMaterial Request` mr INNER JOIN `tabToDo` ta ON ta.reference_type = 'Material Request' AND ta.reference_name = mr.name AND ta.status = 'Open' WHERE mr.docstatus = 1 AND mr.material_request_type = 'Purchase' AND mr.status NOT IN ('Draft', 'Stopped', 'Cancelled') AND mr.workflow_state != 'Cancelled' AND mr.schedule_date <= CURDATE() AND ta.allocated_to = %s AND mr.name NOT IN ('BIO-MR-1176') AND NOT EXISTS (SELECT 1 FROM `tabPurchase Order Item` poi INNER JOIN `tabPurchase Order` po ON po.name = poi.parent WHERE poi.material_request = mr.name AND po.docstatus = 1)
